import{_ as a,o as t,c as o,ao as r}from"./chunks/framework.DA_3JxoV.js";const u=JSON.parse('{"title":"Migration guide","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md","lastUpdated":null}'),n={name:"migration.md"};function i(s,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="Migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#Migration-guide" aria-label="Permalink to &quot;Migration guide {#Migration-guide}&quot;">​</a></h1><p>This page collects notes for upgrading between MPSKit releases when a change requires action on your side. It summarizes the breaking changes recorded in the <a href="/MPSKit.jl/previews/PR449/changelog#Changelog">Changelog</a>; consult that page for the complete, per-version list of changes.</p><h2 id="Unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#Unreleased" aria-label="Permalink to &quot;Unreleased {#Unreleased}&quot;">​</a></h2><h3 id="environments-now-uses-a-single-positional-contract" tabindex="-1"><code>environments</code> now uses a single positional contract <a class="header-anchor" href="#environments-now-uses-a-single-positional-contract" aria-label="Permalink to &quot;`environments` now uses a single positional contract {#environments-now-uses-a-single-positional-contract}&quot;">​</a></h3><p><a href="/MPSKit.jl/previews/PR449/lib/lib#MPSKit.environments"><code>environments</code></a> now follows one positional contract for every state and operator kind:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>environments(below, operator, above, alg)</span></span></code></pre></div><p>where <code>alg</code> (slot 4) is the environment algorithm. The operator form requires an explicit <code>above</code> argument. Auxiliary inputs are now keyword-only: <code>leftstart</code>/<code>rightstart</code> for finite and window environments, and <code>lenvs</code>/<code>renvs</code> for window and quasiparticle environments.</p><p>The two-argument form <code>environments(below, above)</code> (two states) is reserved for the operator-free overlap environments. There is no two-argument <code>environments(below, operator)</code> shorthand: a two-argument call is always interpreted as an overlap, because the second argument cannot be disambiguated between a ket and an operator (this is undecidable for density matrices, where states and operators share a representation). If you previously relied on a two-argument operator call, pass the operator explicitly with an <code>above</code> state. See <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/436" target="_blank" rel="noreferrer">#436</a>.</p><h2 id="Earlier-releases" tabindex="-1">Earlier releases <a class="header-anchor" href="#Earlier-releases" aria-label="Permalink to &quot;Earlier releases {#Earlier-releases}&quot;">​</a></h2><p>The <a href="/MPSKit.jl/previews/PR449/changelog#Changelog">Changelog</a> records further changes across the 0.13.x series, including a refactor of the <code>IDMRG</code> implementation to the <code>IterativeSolver</code> interface (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/348" target="_blank" rel="noreferrer">#348</a>), fixes to <code>changebonds</code> consistency (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/415" target="_blank" rel="noreferrer">#415</a>), and a refactor of time-evolution MPO construction (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/422" target="_blank" rel="noreferrer">#422</a>).</p>',10)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
